import{_ as o,o as r,c as s,a5 as t}from"./chunks/framework.DJo0M80U.js";const _=JSON.parse('{"title":"queueMicrotask()和 Promise.resolve().then(...)","description":"queueMicrotask() 和 Promise.resolve().then(...) 在大多数场景下的 执行时机 几乎一致——都属于 微任务 （microtask），会在当前同步代码执行结束后、下一次事件循环（宏任务）开始前执行回调。它们的区别更多在 实现和语义 上： 1。","frontmatter":{"title":"queueMicrotask()和 Promise.resolve().then(...)","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","异步编程"],"description":"queueMicrotask() 和 Promise.resolve().then(...) 在大多数场景下的 执行时机 几乎一致——都属于 微任务 （microtask），会在当前同步代码执行结束后、下一次事件循环（宏任务）开始前执行回调。它们的区别更多在 实现和语义 上： 1。","sidebarWeight":96,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/11-异步编程/queueMicrotask()和 Promise.resolve().then(...).md"},"headers":[],"relativePath":"posts/JavaScript系统教程/05-异步编程/queueMicrotask()和 Promise.resolve().then(...).md","filePath":"posts/JavaScript系统教程/05-异步编程/queueMicrotask()和 Promise.resolve().then(...).md"}'),i={name:"posts/JavaScript系统教程/05-异步编程/queueMicrotask()和 Promise.resolve().then(...).md"};function n(a,e,l,u,c,m){return r(),s("div",null,[...e[0]||(e[0]=[t('<div><h1 id="queuemicrotask-和-promise-resolve-then" tabindex="-1">queueMicrotask()和 Promise.resolve().then(...) <a class="header-anchor" href="#queuemicrotask-和-promise-resolve-then" aria-label="Permalink to &quot;queueMicrotask()和 Promise.resolve().then(...)&quot;">​</a></h1><blockquote><p>本节目标：理解“queueMicrotask()和 Promise.resolve().then(...)”的核心思路，并能把它用于实际开发或面试表达。 <strong>queueMicrotask()</strong> 和 <strong>Promise.resolve().then(...)</strong> 在大多数场景下的<strong>执行时机</strong>几乎一致——都属于<strong>微任务</strong>（microtask），会在当前同步代码执行结束后、下一次事件循环（宏任务）开始前执行回调。它们的区别更多在<strong>实现和语义</strong>上：</p></blockquote><ol><li><strong>语义更直接</strong>： <ul><li><strong>queueMicrotask()</strong>：明确表示“将一个函数添加到微任务队列中等待执行”。</li><li><strong>Promise.resolve().then(...)</strong>：利用 Promise 的 then 回调也能加入微任务队列，但从语义上它实际上在做 “一个立即resolved的 Promise，然后执行 .then() 回调”。</li></ul></li><li><strong>不需要构造 Promise 对象</strong>： <ul><li>queueMicrotask() 不会额外创建 Promise 实例，性能上更轻量；</li><li>Promise.resolve().then(...) 在底层实现时需要一个新的 Promise 对象。</li></ul></li><li><strong>错误处理与堆栈</strong>： <ul><li><strong>Promise.then()</strong> 允许在 .catch() 中捕获错误并提供回调链条；</li><li><strong>queueMicrotask()</strong> 如果抛出错误，会进入全局错误处理（Uncaught Error），没有 Promise 的错误传递机制。</li></ul></li><li><strong>可读性与意图</strong>： <ul><li><strong>queueMicrotask()</strong> 明确告诉读者“我就是要排一个微任务”；</li><li>Promise.resolve().then 看似一个不必要的 Promise，用来“借用” 微任务队列。</li></ul></li></ol><p><strong>总结</strong>：在<strong>执行顺序</strong>和微任务的时机上，它们效果几乎相同。但 <strong>queueMicrotask()</strong> 更加“原生”，少了一层 Promise 语义和对象开销，也更直观地表达意图。若你只想插入一个简单微任务回调、并不需要链式的 .then() / .catch() 处理逻辑，<strong>queueMicrotask()</strong> 更简洁、更直观。</p></div>',1)])])}const h=o(i,[["render",n]]);export{_ as __pageData,h as default};
